package com.farshekashan.keyfarsi

import android.content.Context
import org.json.JSONObject
import ai.onnxruntime.OnnxTensor
import ai.onnxruntime.OrtEnvironment
import ai.onnxruntime.OrtSession
import java.io.File
import java.io.FileOutputStream
import java.nio.LongBuffer
import kotlin.math.exp
import kotlin.math.ln

/**
 * Offline masked-language-model reranker backed by the pretrained Persian ALBERT checkpoint.
 * The ONNX model/tokenizer are generated by scripts/export_persian_albert_onnx.py and packaged
 * into app/src/main/assets/semantic by the model-assets GitHub Actions workflow.
 */
internal object PersianAlBertSemanticModel {
    private const val ASSET_DIR = "semantic"
    private const val MODEL_FILE = "albert_persian_mlm.onnx"
    private const val SPM_FILE = "spiece.model"
    private const val TOKENS_FILE = "special_tokens.json"
    private const val MAX_TOKENS = 64
    private const val MAX_CANDIDATES = 4
    private const val MAX_PIECES_PER_CANDIDATE = 4

    private data class Runtime(
        val env: OrtEnvironment,
        val session: OrtSession,
        val tokenizer: SentencePieceUnigramTokenizer
    )
    private data class Scored(val match: PersianSpellChecker.Match, val score: Double)

    @Volatile private var runtime: Runtime? = null
    @Volatile private var attempted = false

    @Synchronized private fun getRuntime(context: Context): Runtime? {
        runtime?.let { return it }
        if (attempted) return null
        attempted = true
        return try {
            val model = copyAsset(context, MODEL_FILE)
            val spm = copyAsset(context, SPM_FILE)
            val tokens = JSONObject(context.assets.open("$ASSET_DIR/$TOKENS_FILE").bufferedReader().use { it.readText() })
            val tokenizer = SentencePieceUnigramTokenizer(
                spm.readBytes(),
                clsId = tokens.getInt("cls_token_id"),
                sepId = tokens.getInt("sep_token_id"),
                maskId = tokens.getInt("mask_token_id"),
                unkId = tokens.getInt("unk_token_id"),
                padId = tokens.getInt("pad_token_id")
            )
            val env = OrtEnvironment.getEnvironment()
            val options = OrtSession.SessionOptions().apply { setIntraOpNumThreads(2) }
            val session = try { env.createSession(model.absolutePath, options) } finally { options.close() }
            Runtime(env, session, tokenizer).also { runtime = it }
        } catch (_: Exception) {
            // Keep the keyboard usable if the optional model assets are absent or invalid.
            null
        }
    }

    private fun copyAsset(context: Context, name: String): File {
        val dir = File(context.filesDir, "keyfarsi-semantic-model").apply { mkdirs() }
        val out = File(dir, name)
        if (!out.exists() || out.length() == 0L) {
            context.assets.open("$ASSET_DIR/$name").use { input ->
                FileOutputStream(out).use { output -> input.copyTo(output) }
            }
        }
        return out
    }

    /** Returns the best candidate only when the pretrained model has a clear contextual margin. */
    fun confidentCorrection(
        context: Context,
        prefixBeforeTypedWord: String,
        matches: List<PersianSpellChecker.Match>
    ): String? {
        if (matches.size < 2 || prefixBeforeTypedWord.isBlank()) return null
        val scored = scoreCandidates(context, prefixBeforeTypedWord, matches)
        if (scored.size < 2) return null
        val best = scored[0]
        val second = scored[1]
        // MLM scores are mean log-probabilities. A margin is required to avoid speculative edits.
        if (best.match.distance > 3 || best.score - second.score < 0.70) return null
        return best.match.word
    }

    private fun scoreCandidates(
        context: Context,
        prefix: String,
        matches: List<PersianSpellChecker.Match>
    ): List<Scored> {
        val rt = getRuntime(context) ?: return emptyList()
        return matches.asSequence().take(MAX_CANDIDATES).mapNotNull { match ->
            try {
                val score = pseudoLogLikelihood(rt, prefix, match.word)
                if (score.isFinite()) Scored(match, score) else null
            } catch (_: Exception) { null }
        }.sortedByDescending { it.score }.toList()
    }

    /**
     * Pseudo-log-likelihood for a candidate. All candidate pieces are masked in a single
     * batched ONNX call instead of one call per subword. This keeps contextual ranking practical
     * on mobile CPUs while preserving the official MLM objective.
     */
    private fun pseudoLogLikelihood(rt: Runtime, prefixRaw: String, candidate: String): Double {
        val prefix = prefixRaw.trim().takeLast(220)
        val prefixIds = rt.tokenizer.encodePieces(prefix)
        val candidateIds = rt.tokenizer.encodePieces(candidate)
        if (candidateIds.isEmpty() || candidateIds.size > MAX_PIECES_PER_CANDIDATE) {
            return Double.NEGATIVE_INFINITY
        }
        val keptPrefix = prefixIds.takeLast((MAX_TOKENS - 2 - candidateIds.size).coerceAtLeast(0))
        val all = keptPrefix + candidateIds
        val candidateStart = 1 + keptPrefix.size
        val ids = LongArray(all.size + 2)
        ids[0] = rt.tokenizer.specialClsId().toLong()
        all.forEachIndexed { i, id -> ids[i + 1] = id.toLong() }
        ids[ids.lastIndex] = rt.tokenizer.specialSepId().toLong()

        val positions = candidateIds.indices.map { candidateStart + it }
        if (positions.any { it !in 1 until ids.lastIndex }) return Double.NEGATIVE_INFINITY
        val batchSize = positions.size
        val seqLength = ids.size
        val batchedIds = LongArray(batchSize * seqLength)
        for (row in 0 until batchSize) {
            val offset = row * seqLength
            ids.copyInto(batchedIds, offset)
            batchedIds[offset + positions[row]] = rt.tokenizer.specialMaskId().toLong()
        }
        val attention = LongArray(batchSize * seqLength) { 1L }
        val types = LongArray(batchSize * seqLength)
        val inputIds = OnnxTensor.createTensor(
            rt.env, LongBuffer.wrap(batchedIds), longArrayOf(batchSize.toLong(), seqLength.toLong())
        )
        val attentionMask = OnnxTensor.createTensor(
            rt.env, LongBuffer.wrap(attention), longArrayOf(batchSize.toLong(), seqLength.toLong())
        )
        val tokenTypes = OnnxTensor.createTensor(
            rt.env, LongBuffer.wrap(types), longArrayOf(batchSize.toLong(), seqLength.toLong())
        )
        try {
            val inputs = mapOf(
                "input_ids" to inputIds,
                "attention_mask" to attentionMask,
                "token_type_ids" to tokenTypes
            )
            rt.session.run(inputs).use { result ->
                val tensor = result[0] as OnnxTensor
                @Suppress("UNCHECKED_CAST")
                val logits = tensor.value as Array<Array<FloatArray>>
                var total = 0.0
                var count = 0
                for (row in positions.indices) {
                    val tokenLogits = logits[row][positions[row]]
                    val expected = candidateIds[row]
                    if (expected !in tokenLogits.indices) continue
                    var maxLogit = Float.NEGATIVE_INFINITY
                    for (value in tokenLogits) if (value > maxLogit) maxLogit = value
                    var expSum = 0.0
                    for (value in tokenLogits) expSum += exp((value - maxLogit).toDouble())
                    total += (tokenLogits[expected] - maxLogit).toDouble() - ln(expSum)
                    count++
                }
                return if (count == 0) Double.NEGATIVE_INFINITY else total / count
            }
        } finally {
            inputIds.close()
            attentionMask.close()
            tokenTypes.close()
        }
    }

}
